declare(strict_types=1);

/**
 * lote18.php — La aptitud del conductor: TWIC, estatus y récord.
 *
 * REQUIERE los lotes 12 a 17 aplicados.
 *
 * Es la primera mitad de lo que pediste: este lado guarda los HECHOS del
 * conductor. La segunda mitad —los REQUISITOS de cada carga y la comparación
 * cumple / no cumple / no consta— va en el lote siguiente.
 *
 * Qué instala:
 *   • Doce columnas en `drivers`: TWIC (tiene, últimos cuatro dígitos,
 *     caducidad), autorización de trabajo, y récord limpio de N años. Cada
 *     bloque con su `..._verified_at` y su `..._verified_by_user_id`.
 *   • `App\Enums\WorkAuthorization`, opcional y nullable a propósito.
 *   • La sección de Aptitud en el formulario del conductor.
 *   • 9 pruebas Pest.
 *
 * TRES COSAS QUE NO SON DE ESTILO
 *
 *   • NADA de esto se comprueba solo. No se consulta al TSA ni se pide un MVR:
 *     alguien mira el documento y el guardado deja constancia de quién y
 *     cuándo. Por eso no existe ninguna columna que diga «verificado» a secas.
 *   • El sello solo se pone cuando el dato CAMBIA. Re-sellar en cada guardado
 *     haría que la fecha dijera «hoy» para siempre y dejara de significar nada.
 *   • `work_authorization` es opcional y lo seguirá siendo. Filtrar cargas por
 *     ese campo solo es defendible cuando la CARGA declara por escrito de dónde
 *     sale el requisito — y eso se guarda del lado de la carga, en el lote
 *     siguiente. Esto no es asesoramiento legal.
 *
 * El DDL de la migración se ejecutó contra un MySQL 8.0.46 real antes de
 * empaquetar esto: las dos restricciones CHECK y las tres claves ajenas se
 * probaron con datos que debían pasar y con datos que debían fallar.
 *
 * Cómo se ejecuta, desde la raíz del repositorio:
 *
 *     php lote18.php            # aplica
 *     php lote18.php --dry-run  # dice qué haría y no toca nada
 *
 * Es idempotente: un trozo ya aplicado se salta. Si un fichero no está donde
 * este guion espera, ABORTA sin escribir nada — no adivina.
 */

$raiz = __DIR__;
$dry = in_array('--dry-run', $argv, true);

$hechos = [];
$saltados = [];
$errores = [];

function ruta(string $rel): string
{
    global $raiz;

    return $raiz.DIRECTORY_SEPARATOR.$rel;
}

/** Escribe un fichero nuevo (o lo deja igual si ya tiene ese contenido). */
function nuevo(string $rel, string $contenido): void
{
    global $dry, $hechos, $saltados, $errores;

    $destino = ruta($rel);

    if (is_file($destino) && file_get_contents($destino) === $contenido) {
        $saltados[] = "= {$rel}";

        return;
    }

    $existia = is_file($destino);

    if ($dry) {
        $hechos[] = ($existia ? '~ ' : '+ ').$rel;

        return;
    }

    $dir = dirname($destino);

    if (! is_dir($dir) && ! mkdir($dir, 0775, true) && ! is_dir($dir)) {
        $errores[] = "no se pudo crear el directorio {$dir}";

        return;
    }

    if (file_put_contents($destino, $contenido) === false) {
        $errores[] = "no se pudo escribir {$rel}";

        return;
    }

    $hechos[] = ($existia ? '~ ' : '+ ').$rel;
}

/**
 * Aplica trozos anclados sobre un fichero existente.
 *
 * Para cada par: si el resultado YA está, se salta; si el texto de partida está
 * una sola vez, se sustituye; en cualquier otro caso, se aborta el fichero
 * entero sin escribir. Un anclaje que no encaja significa que el fichero no es
 * el que este guion vio, y adivinar ahí es peor que parar.
 *
 * @param  list<array{0: string, 1: string}>  $pares
 */
function editar(string $rel, array $pares): void
{
    global $dry, $hechos, $saltados, $errores;

    $destino = ruta($rel);

    if (! is_file($destino)) {
        $errores[] = "falta {$rel} — ¿está en la raíz del repositorio?";

        return;
    }

    $texto = file_get_contents($destino);
    $aplicados = 0;
    $yaEstaban = 0;

    foreach ($pares as $i => [$antes, $despues]) {
        if (str_contains($texto, $despues)) {
            $yaEstaban++;

            continue;
        }

        $veces = substr_count($texto, $antes);

        if ($veces !== 1) {
            $errores[] = "{$rel}: el trozo #".($i + 1)." no encaja ({$veces} coincidencias). No se tocó el fichero.";

            return;
        }

        $texto = str_replace($antes, $despues, $texto);
        $aplicados++;
    }

    if ($aplicados === 0) {
        $saltados[] = "= {$rel} ({$yaEstaban} trozo(s) ya estaban)";

        return;
    }

    if ($dry) {
        $hechos[] = "~ {$rel} ({$aplicados} trozo(s))";

        return;
    }

    if (file_put_contents($destino, $texto) === false) {
        $errores[] = "no se pudo escribir {$rel}";

        return;
    }

    $hechos[] = "~ {$rel} ({$aplicados} trozo(s))";
}

foreach (['artisan', 'composer.json', 'app/Support/Navigation.php'] as $centinela) {
    if (! is_file(ruta($centinela))) {
        fwrite(STDERR, "Esto no parece la raíz del repositorio: falta {$centinela}.\n");
        exit(1);
    }
}

